// C#: Gọi dịch vụ phụ thuộc với Timeout + Circuit Breaker (Polly)
var policy = Policy.WrapAsync(
    Policy.Handle<Exception>().CircuitBreakerAsync(5, TimeSpan.FromSeconds(30)),
    Policy.TimeoutAsync(TimeSpan.FromSeconds(3)));

var result = await policy.ExecuteAsync(
    ct => _client.GetAsync(url, ct), CancellationToken.None);
